#define MAX_NODES 1000
#define INF 1000000000

int adj[MAX_NODES][MAX_NODES];
int deg[MAX_NODES];
int dist[MAX_NODES];
int queue[MAX_NODES];
int front, rear;

void bfs(int start, int n) {
    for (int i = 0; i < n; i++) {
        dist[i] = INF;
    }
    dist[start] = 0;
    front = rear = 0;
    queue[rear++] = start;

    while (front < rear) {
        int u = queue[front++];
        for (int i = 0; i < deg[u]; i++) {
            int v = adj[u][i];
            if (dist[v] > dist[u] + 1) {
                dist[v] = dist[u] + 1;
                queue[rear++] = v;
            }
        }
    }
}

