typedef struct {
    int *data;
    int size;
    int cap;
} Vec;

static void vec_init(Vec *v) {
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, int x) {
    if (v->size == v->cap) {
        int ncap = (v->cap == 0) ? 4 : v->cap * 2;
        int *nd = (int *)realloc(v->data, ncap * sizeof(int));
        if (!nd) exit(1);
        v->data = nd;
        v->cap = ncap;
    }
    v->data[v->size++] = x;
}

typedef struct {
    int *data;
    int head, tail, cap;
} Queue;

static void q_init(Queue *q, int cap) {
    q->data = (int *)malloc(cap * sizeof(int));
    if (!q->data) exit(1);
    q->head = q->tail = 0;
    q->cap = cap;
}

static int q_empty(Queue *q) {
    return q->head == q->tail;
}

static void q_push(Queue *q, int x) {
    q->data[q->tail++] = x;
}

static int q_pop(Queue *q) {
    return q->data[q->head++];
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Vec *adj = (Vec *)malloc((N + 1) * sizeof(Vec));
    if (!adj) return 0;
    for (int i = 1; i <= N; i++) vec_init(&adj[i]);

    /*
      Input format assumed:
      N
      For i = 1..N:
        k v1 v2 ... vk
      Q
      Q lines:
        s t

      Output:
      Minimum number of routers passed through from s to t
      (minimum number of edges), or NA if unreachable.
    */

    for (int i = 1; i <= N; i++) {
        int k;
        scanf("%d", &k);
        for (int j = 0; j < k; j++) {
            int to;
            scanf("%d", &to);
            if (1 <= to && to <= N) vec_push(&adj[i], to);
        }
    }

    int Qn;
    scanf("%d", &Qn);

    int *dist = (int *)malloc((N + 1) * sizeof(int));
    if (!dist) return 0;

    while (Qn--) {
        int s, t;
        scanf("%d", &s, &t);

        for (int i = 1; i <= N; i++) dist[i] = -1;

        Queue q;
        q_init(&q, N + 5);

        dist[s] = 0;
        q_push(&q, s);

        while (!q_empty(&q)) {
            int u = q_pop(&q);
            if (u == t) break;
            for (int i = 0; i < adj[u].size; i++) {
                int v = adj[u].data[i];
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q_push(&q, v);
                }
            }
        }

        if (dist[t] == -1) printf("NA\n");
        else printf("%d\n", dist[t]);

        free(q.data);
    }

    for (int i = 1; i <= N; i++) free(adj[i].data);
    free(adj);
    free(dist);

    return 0;
}

