    if not data:
        return
    it = iter(data)

    n = int(next(it))  # number of routers
    # adjacency list: for each router (0-indexed), list of neighbors
    adj = [[] for _ in range(n)]
    for i in range(n):
        cnt = int(next(it))
        for _ in range(cnt):
            v = int(next(it))
            adj[i].append(v)

    m = int(next(it))  # number of packets
    out_lines = []
    for _ in range(m):
        s = int(next(it))
        t = int(next(it))
        # BFS from s to t
        dist = [-1] * n
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            if u == t:
                break
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        if dist[t] != -1:
            out_lines.append(str(dist[t]))
        else:
            out_lines.append("NA")

    sys.stdout.write("\n".join(out_lines))

