import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        // Read the number of routers
        line = br.readLine();
        if (line == null) return;
        int n = Integer.parseInt(line.trim());

        // Build adjacency list
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        // Read connections for each router
        for (int i = 0; i < n; i++) {
            line = br.readLine();
            if (line == null) break;
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            for (String part : parts) {
                int neighbor = Integer.parseInt(part);
                graph.get(i).add(neighbor);
            }
        }

        // Read number of packets
        line = br.readLine();
        if (line == null) return;
        int p = Integer.parseInt(line.trim());

        // Process each packet
        for (int i = 0; i < p; i++) {
            line = br.readLine();
            if (line == null) break;
            String[] parts = line.split(" ");
            int src = Integer.parseInt(parts[0]);
            int dst = Integer.parseInt(parts[1]);
            int ttl = Integer.parseInt(parts[2]);

            // BFS to find shortest path from src to dst
            int result = bfs(graph, n, src, dst, ttl);
            if (result == -1) {
                System.out.println("NA");
            } else {
                System.out.println(result);
            }
        }
    }

    private static int bfs(List<List<Integer>> graph, int n, int src, int dst, int ttl) {
        if (src == dst) return 0; // Already at destination

        // Distance array: -1 means not visited
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        dist[src] = 0;

        Queue<Integer> queue = new LinkedList<>();
        queue.offer(src);

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            int currentDist = dist[curr];

            // If we reached the destination, return the distance
            if (curr == dst) {
                return currentDist;
            }

            // If current distance + 1 would exceed TTL, skip forwarding
            if (currentDist + 1 > ttl) continue;

            for (int neighbor : graph.get(curr)) {
                if (dist[neighbor] == -1) {
                    dist[neighbor] = currentDist + 1;
                    queue.offer(neighbor);
                }
            }
        }

        // Destination not reachable within TTL
        return -1;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) graph[i] = new ArrayList<>();

        // For each router i:
        // k v1 v2 ... vk
        for (int i = 1; i <= n; i++) {
            int k = fs.nextInt();
            for (int j = 0; j < k; j++) {
                graph[i].add(fs.nextInt());
            }
        }

        int q = fs.nextInt();
        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < q; qi++) {
            int src = fs.nextInt();
            int dst = fs.nextInt();

            int ans = bfs(graph, n, src, dst);
            if (ans == -1) out.append("NA");
            else out.append(ans);

            if (qi + 1 < q) out.append('\n');
        }

        System.out.print(out.toString());
    }

    static int bfs(List<Integer>[] graph, int n, int src, int dst) {
        if (src == dst) return 0;

        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();

        dist[src] = 0;
        q.add(src);

        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int nxt : graph[cur]) {
                if (dist[nxt] != -1) continue;
                dist[nxt] = dist[cur] + 1;
                if (nxt == dst) return dist[nxt];
                q.add(nxt);
            }
        }
        return -1;
    }
}
